#include <iostream>

int fibonacci(int n) {
    if (n <= 1) {
        return n;
    }

    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    int n;

    std::cout << "Enter a positive integer: ";
    std::cin >> n;

    if (n < 0) {
        std::cout << "Invalid input! The number must be positive." << std::endl;
        return 0;
    }

    int fib = fibonacci(n);

    std::cout << "The " << n << "th Fibonacci number is: " << fib << std::endl;

    return 0;
}
```

